const prices={sedan:[25000,45000,25000],suv:[35000,60000,35000],van:[40000,70000,40000]},names=['Гадна угаалга','Бүтэн угаалга','Дотор цэвэрлэгээ'];
const form=document.querySelector('form'),el=form.elements,key='nomad-demo-orders-v1';let coords=null;
const money=n=>n.toLocaleString('en-US')+'₮';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ulaanbaatar',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function read(){try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return []}}
function duration(service){return Number(service)===1?2:1}
function available(date,hour,service,orders=read()){if(date<today())return false;const nowHour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Ulaanbaatar',hour:'2-digit',hourCycle:'h23'}).format(new Date()));if(date===today()&&hour<=nowHour)return false;if(hour+duration(service)>19)return false;for(let t=hour;t<hour+duration(service);t++){if(orders.filter(o=>o.date===date&&o.status!=='cancelled'&&Number(o.time)<=t&&Number(o.time)+duration(o.service)>t).length>=2)return false}return true}
function renderSlots(){const root=document.querySelector('#slots');root.replaceChildren();for(let h=9;h<19;h++){const b=document.createElement('button');b.type='button';b.textContent=String(h).padStart(2,'0')+':00';b.disabled=!available(el.date.value,h,el.service.value);b.classList.toggle('selected',el.time.value===String(h)&&!b.disabled);b.onclick=()=>{el.time.value=h;renderSlots()};root.append(b)}if(el.time.value&&!available(el.date.value,Number(el.time.value),el.service.value))el.time.value=''}
function update(){document.querySelectorAll('[data-price]').forEach(p=>p.innerHTML=money(prices[el.car.value][p.dataset.price])+' <small>/ удаа</small>');document.querySelector('#total').textContent=money(prices[el.car.value][el.service.value]);document.querySelectorAll('[data-car]').forEach(b=>b.classList.toggle('active',b.dataset.car===el.car.value));renderSlots()}
document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>{el.car.value=b.dataset.car;update()});document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{el.service.value=b.dataset.service;update();document.querySelector('#booking').scrollIntoView({behavior:'smooth'})});['car','service','date'].forEach(n=>el[n].addEventListener('change',update));el.date.min=today();el.date.value=today();
document.querySelector('#locate').onclick=()=>{const out=document.querySelector('#location-result');if(!navigator.geolocation){out.textContent='Байршил дэмжигдэхгүй. Хаягаа гараар оруулна уу.';return}out.textContent='Байршил хайж байна…';navigator.geolocation.getCurrentPosition(p=>{coords={lat:p.coords.latitude,lng:p.coords.longitude};out.textContent=`Байршил сонгогдлоо: ${coords.lat.toFixed(5)}, ${coords.lng.toFixed(5)}`},()=>{out.textContent='Байршил авч чадсангүй. Хаягаа гараар оруулна уу.'},{timeout:12000})};
form.onsubmit=async e=>{e.preventDefault();const msg=document.querySelector('#form-message');const save=()=>{const orders=read();if(!el.time.value||!available(el.date.value,Number(el.time.value),el.service.value,orders)){msg.textContent='Боломжтой цаг сонгоно уу.';renderSlots();return}const order=Object.fromEntries(new FormData(form));order.id=crypto.randomUUID();order.coords=coords;order.status='pending';order.price=prices[order.car][order.service];try{localStorage.setItem(key,JSON.stringify([...orders,order]))}catch{msg.textContent='Хадгалж чадсангүй. Хөтчийн хадгалах эрхийг шалгана уу.';return}msg.textContent=`✓ Демо захиалга хадгалагдлаа: ${order.date}, ${String(order.time).padStart(2,'0')}:00. Админ демо хэсгээс хараарай. Бодит мэдэгдэл илгээгдээгүй.`;form.reset();coords=null;document.querySelector('#location-result').textContent='Хаягаа гараар оруулж болно';el.date.value=today();el.time.value='';update()};if(navigator.locks)await navigator.locks.request(key,save);else save()};
const admin=document.querySelector('#admin');document.querySelector('#admin-open').onclick=()=>{document.querySelector('#admin-date').value=today();renderOrders();admin.showModal()};document.querySelector('#admin-close').onclick=()=>admin.close();document.querySelector('#admin-date').onchange=renderOrders;
function renderOrders(){const root=document.querySelector('#orders'),date=document.querySelector('#admin-date').value;root.replaceChildren();const orders=read().filter(o=>!date||o.date===date).sort((a,b)=>Number(a.time)-Number(b.time));if(!orders.length){root.textContent='Энэ өдөр захиалга алга.';return}for(const o of orders){const card=document.createElement('article');card.className='order';const title=document.createElement('strong');title.textContent=`${String(o.time).padStart(2,'0')}:00 · ${o.name} · ${names[o.service]}`;const detail=document.createElement('p');detail.textContent=`${o.phone} · ${o.model} · ${o.plate}\n${o.address}\n${money(o.price)}`;card.append(title,detail);if(o.coords){const a=document.createElement('a');a.href=`https://www.google.com/maps?q=${Number(o.coords.lat)},${Number(o.coords.lng)}`;a.target='_blank';a.rel='noopener';a.textContent='Байршил харах ↗';card.append(a)}const select=document.createElement('select');select.setAttribute('aria-label','Захиалгын төлөв');for(const [value,text]of [['pending','Хүлээгдэж буй'],['done','Хийгдсэн'],['cancelled','Цуцлагдсан']]){const opt=new Option(text,value);select.add(opt)}select.value=o.status;select.disabled=o.status==='cancelled';select.onchange=()=>{const all=read();const found=all.find(x=>x.id===o.id);if(found){found.status=select.value;try{localStorage.setItem(key,JSON.stringify(all));renderOrders();renderSlots()}catch{alert('Төлөв хадгалж чадсангүй.')}}};card.append(select);root.append(card)}}window.addEventListener('storage',()=>{update();if(admin.open)renderOrders()});update();
const easyScript=document.createElement('script');easyScript.src='easy-custom.js';document.body.append(easyScript);
